// Works out the look-back window. Scan Registrations then pages through every upcoming,
// active registration changed inside it, so a missed run is caught by the next one.
const cfgObj = $('Config').first().json;
const sinceStr = $now.minus({ minutes: Number(cfgObj.LOOKBACK_MINUTES) || 180 }).toUTC().toFormat("yyyy-MM-dd'T'HH:mm:ss'Z'");
const queryStr = 'query ScanRegistrations($today: String!, $since: String!, $first: Int, $after: String) { learners(first: $first, after: $after, filters: [' +
  '{ field: isActive, operation: eq, value: "true" }, ' +
  '{ field: eventStartDate, operation: ge, value: $today }, ' +
  '{ field: lastUpdatedAt, operation: ge, value: $since }' +
  ']) { pageInfo { hasNextPage endCursor } edges { node { id notes contact { id emailAddress personalName { firstName lastName } } event { id } customFieldValues { definitionKey value } } } } }';
return [{ json: { scanQuery: queryStr, today: $now.toISODate(), since: sinceStr, pageSize: Number(cfgObj.SCAN_PAGE_SIZE) || 100 } }];

// Keeps only the registrations flagged for substitution: one item per request.
// Scan Registrations returns one item per page of results.
const cfgObj = $('Config').first().json;
const pagesAry = $input.all();
const outAry = [];
const seenObj = {};
for (const pageObj of pagesAry) {
  const resObj = pageObj.json || {};
  if (resObj.errors || !resObj.data || !resObj.data.learners) {
    throw new Error('Scan query failed: ' + JSON.stringify(resObj.errors || resObj).slice(0, 500));
  }
  for (const edgeObj of (resObj.data.learners.edges || [])) {
    const lObj = edgeObj.node || {};
    if (!lObj.id || seenObj[lObj.id]) { continue; }
    seenObj[lObj.id] = true;
    const cfObj = {};
    for (const vObj of (lObj.customFieldValues || [])) { cfObj[vObj.definitionKey] = vObj.value; }
    if (cfObj[cfgObj.CHANGE_TYPE_FIELD_KEY] !== cfgObj.VALUE_REQUESTED) { continue; }
    const contactObj = lObj.contact || {};
    const nameObj = contactObj.personalName || {};
    outAry.push({ json: {
      learnerId: lObj.id,
      learnerNotes: lObj.notes || '',
      eventId: (lObj.event || {}).id || '',
      outgoingContactId: contactObj.id || '',
      outgoingEmail: contactObj.emailAddress || '',
      outgoingName: ((nameObj.firstName || '') + ' ' + (nameObj.lastName || '')).trim(),
      replacementEmail: String(cfObj[cfgObj.SUBSTITUTE_EMAIL_FIELD_KEY] || '').trim().toLowerCase()
    } });
  }
}
// A partial scan must not pass for a complete one: stop and say so.
const lastObj = (pagesAry[pagesAry.length - 1] || {}).json || {};
if ((((lastObj.data || {}).learners || {}).pageInfo || {}).hasNextPage) {
  throw new Error('Scan stopped at the page limit before reading every changed registration. Shorten LOOKBACK_MINUTES or raise SCAN_PAGE_SIZE (100 at most), then run again.');
}
return outAry;

// Checks the request against live data and prepares the writes. Nothing is written here.
// Existing registrations and capacity are checked next, in Confirm Not Registered.
const reqObj = $('Loop Over Requests').item.json;
const resObj = $json || {};
const stampStr = $now.toUTC().toFormat('yyyy-MM-dd HH:mm') + ' UTC';
const baseObj = Object.assign({}, reqObj, { stamp: stampStr });
const refuseFn = function (reasonStr) { return { json: Object.assign(baseObj, { action: 'refuse', reason: reasonStr }) }; };
if (resObj.errors || !resObj.data) { return { json: Object.assign(baseObj, { action: 'skip', reason: 'Read failed, will retry on the next run: ' + JSON.stringify(resObj.errors || resObj).slice(0, 300) }) }; }
if (!reqObj.replacementEmail) { return refuseFn('No substitute email was entered.'); }
const contactsAry = (((resObj.data.contacts || {}).edges) || []).map(function (eObj) { return eObj.node; });
const eventObj = ((((resObj.data.events || {}).edges) || [])[0] || {}).node;
if (!eventObj) { return refuseFn('The event could not be read.'); }
if (contactsAry.length === 0) { return refuseFn('No contact found with the email ' + reqObj.replacementEmail + '.'); }
if (contactsAry.length > 1) { return refuseFn('Several contacts share the email ' + reqObj.replacementEmail + '.'); }
const inObj = contactsAry[0];
if (inObj.id === reqObj.outgoingContactId) { return refuseFn('The substitute is the same person as the learner giving up the place.'); }
const inNameStr = (((inObj.personalName || {}).firstName || '') + ' ' + ((inObj.personalName || {}).lastName || '')).trim();
const lineStr = '[Substitution ' + stampStr + '] ' + reqObj.outgoingName + ' released the place and ' + inNameStr + ' was registered instead. This is a substitution, not a withdrawal.';
return { json: Object.assign(baseObj, {
  action: 'substitute',
  incomingContactId: inObj.id,
  incomingEmail: inObj.emailAddress || '',
  incomingName: inNameStr,
  incomingFirstName: (inObj.personalName || {}).firstName || inNameStr,
  eventCode: eventObj.code || '',
  eventTitle: eventObj.title || '',
  eventStart: String(eventObj.start || '').slice(0, 16).replace('T', ' '),
  eventLocation: (eventObj.location || {}).name || '',
  eventRemainingPlaces: eventObj.remainingPlaces,
  auditLine: lineStr
}) };

// Looks at any active registration the substitute already has on the event.
// One created by an earlier, interrupted run for this same request is resumed;
// any other one is refused. Capacity is only checked for a fresh substitution.
const cfgObj = $('Config').first().json;
const decObj = $('Decide').item.json;
if (decObj.action !== 'substitute') { return { json: decObj }; }
const resObj = $json || {};
if (resObj.errors || !resObj.data || !resObj.data.learners) {
  return { json: Object.assign({}, decObj, { action: 'skip', reason: 'Registration check failed, will retry on the next run: ' + JSON.stringify(resObj.errors || resObj).slice(0, 300) }) };
}
const foundAry = (resObj.data.learners.edges || []).map(function (eObj) { return eObj.node; });
if (foundAry.length > 0) {
  const cfObj = {};
  for (const vObj of (foundAry[0].customFieldValues || [])) { cfObj[vObj.definitionKey] = vObj.value; }
  const sameRequestBool = cfObj[cfgObj.CHANGE_TYPE_FIELD_KEY] === cfgObj.VALUE_TAKEN_OVER &&
    String(cfObj[cfgObj.SUBSTITUTE_EMAIL_FIELD_KEY] || '').trim().toLowerCase() === String(decObj.outgoingEmail || '').trim().toLowerCase();
  if (sameRequestBool) {
    return { json: Object.assign({}, decObj, { action: 'resume', incomingLearnerId: foundAry[0].id, reason: 'The substitute was registered by an earlier run; finishing the release.' }) };
  }
  return { json: Object.assign({}, decObj, { action: 'refuse', reason: decObj.incomingName + ' is already registered on this event.' }) };
}
const placesAny = decObj.eventRemainingPlaces;
if (placesAny !== null && placesAny !== undefined && Number(placesAny) <= 0) {
  return { json: Object.assign({}, decObj, { action: 'refuse', reason: 'The event is full. The substitute is registered before the place is released, so a full event needs one place freed by an administrator first.' }) };
}
return { json: decObj };

// registerNamedLearners returns a list of results, one per learner in the input.
// A domain error (Administrate refused) becomes a refusal; anything unexpected stops the run,
// and the request is picked up again on the next run.
const decObj = $('Confirm Not Registered').item.json;
const resObj = $json || {};
const rawAny = ((resObj.data || {}).event || {}).registerNamedLearners;
if (resObj.errors || rawAny === undefined || rawAny === null) {
  throw new Error('No usable response from Administrate when registering ' + decObj.incomingName + ' on event ' + decObj.eventId + ': ' + JSON.stringify(resObj.errors || resObj).slice(0, 300));
}
const resultsAry = Array.isArray(rawAny) ? rawAny : [rawAny];
let errsAry = [];
let learnersAry = [];
for (const rObj of resultsAry) {
  errsAry = errsAry.concat((rObj && rObj.errors) || []);
  learnersAry = learnersAry.concat((rObj && rObj.learners) || []);
}
const okBool = errsAry.length === 0 && learnersAry.length > 0;
return { json: Object.assign({}, decObj, {
  registered: okBool,
  incomingLearnerId: okBool ? learnersAry[0].id : '',
  reason: okBool ? '' : 'Administrate refused to register the substitute: ' + (errsAry.map(function (eObj) { return eObj.message; }).join('; ') || 'no learner was returned')
}) };

// The substitute is registered at this point. Every expected result must be present
// and clean; otherwise stop with the details so an administrator can finish by hand.
const decObj = $('Confirm Not Registered').item.json;
const resObj = $json || {};
const dObj = resObj.data || {};
const tagObj = (dObj.tag || {}).update;
const cancelObj = (dObj.cancel || {}).cancel;
const errsAry = (resObj.errors || []).concat((tagObj && tagObj.errors) || []).concat((cancelObj && cancelObj.errors) || []);
if (!tagObj || !cancelObj || errsAry.length > 0) {
  throw new Error('Substitute ' + decObj.incomingName + ' is registered on event ' + decObj.eventId + ' but releasing the place of ' + decObj.outgoingName + ' (learner ' + decObj.learnerId + ') did not complete: ' + (errsAry.map(function (eObj) { return eObj.message; }).join('; ') || 'missing response') + '. Finish it by hand.');
}
return { json: decObj };

// Written only after the release is verified, so a success entry is always true.
const decObj = $('Check Release').item.json;
const resObj = $json || {};
const logObj = ((resObj.data || {}).externalLog || {}).createExternalIntegrationLog;
const errsAry = (resObj.errors || []).concat((logObj && logObj.errors) || []);
if (!logObj || errsAry.length > 0) {
  throw new Error('Substitution for ' + decObj.outgoingName + ' on event ' + decObj.eventId + ' is complete, but the success log could not be written: ' + (errsAry.map(function (eObj) { return eObj.message; }).join('; ') || 'missing response'));
}
return { json: decObj };

const cfgObj = $('Config').first().json;
const dObj = $json;
const escFn = function (vAny) { return String(vAny === null || vAny === undefined ? '' : vAny).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;').split('"').join('&quot;'); };
const rowFn = function (kStr, vStr) { return '<tr><td style="padding:8px 0;color:#5A6472;font-size:13px;width:160px;">' + escFn(kStr) + '</td><td style="padding:8px 0;color:#16202B;font-size:14px;">' + escFn(vStr) + '</td></tr>'; };
const htmlStr = '<div style="font-family:Arial,Helvetica,sans-serif;background:#F4F6F8;padding:24px;"><table width="600" cellpadding="0" cellspacing="0" style="background:#FFFFFF;border-radius:8px;"><tr><td style="background:' + escFn(cfgObj.BRAND_COLOUR) + ';padding:18px 24px;color:#FFFFFF;font-size:18px;font-weight:bold;">' + escFn(cfgObj.BRAND_NAME) + '</td></tr><tr><td style="padding:24px;"><p style="font-size:15px;color:#16202B;">Hello ' + escFn(dObj.incomingFirstName) + ',</p><p style="font-size:15px;color:#16202B;">' + escFn(dObj.outgoingName) + ' can no longer attend <strong>' + escFn(dObj.eventTitle) + '</strong> and the place has been transferred to you. Your registration is confirmed.</p><table cellpadding="0" cellspacing="0" style="margin:16px 0;">' + rowFn('Event', dObj.eventCode) + rowFn('Starts', dObj.eventStart) + rowFn('Location', dObj.eventLocation) + '</table><p style="font-size:13px;color:#5A6472;">If you cannot attend, please let us know as soon as possible so the place can be offered to someone else.</p></td></tr></table></div>';
return { json: Object.assign({}, dObj, { emailBody: { query: 'mutation SendSubstitutionEmail($subject: String!, $body: String!) { contactAdhocEmails { sendContactAdhocEmail(input: { contactId: ' + JSON.stringify(dObj.incomingContactId) + ', subject: $subject, body: $body, sendingAddressId: ' + JSON.stringify(cfgObj.SENDING_ADDRESS_ID) + ' }) { errors { label message value } } } }', variables: { subject: 'A place has been transferred to you: ' + dObj.eventTitle, body: htmlStr } } }) };

const decObj = $('Build Email').item.json;
const resObj = $json || {};
const sendObj = ((resObj.data || {}).contactAdhocEmails || {}).sendContactAdhocEmail;
const errsAry = (resObj.errors || []).concat((sendObj && sendObj.errors) || []);
if (!sendObj || errsAry.length > 0) {
  throw new Error('Substitution for ' + decObj.outgoingName + ' is complete, but the confirmation email to ' + decObj.incomingName + ' was not sent: ' + (errsAry.map(function (eObj) { return eObj.message; }).join('; ') || 'missing response'));
}
return { json: { learnerId: decObj.learnerId, outcome: 'substituted' } };

// Marks the request as refused on the registration, with the reason in its notes,
// so the administrator sees why and the next run does not try again.
const cfgObj = $('Config').first().json;
const dObj = $json;
const lineStr = '[Substitution refused ' + dObj.stamp + '] ' + dObj.reason;
const notesStr = (dObj.learnerNotes ? dObj.learnerNotes + String.fromCharCode(10) : '') + lineStr;
const logPartStr = dObj.eventId ? ' log: externalLog { createExternalIntegrationLog(input: { originIdentifier: $origin, nodeId: ' + JSON.stringify(dObj.eventId) + ', message: $message, status: failed }) { errors { label message value } } }' : '';
const queryStr = 'mutation RefuseSubstitution($notes: String, $message: String!, $origin: String!) { tag: learner { update(input: { learnerId: ' + JSON.stringify(dObj.learnerId) + ', notes: $notes, customFieldValues: [{ definitionKey: ' + JSON.stringify(cfgObj.CHANGE_TYPE_FIELD_KEY) + ', value: ' + JSON.stringify(cfgObj.VALUE_REFUSED) + ' }] }) { errors { label message value } } }' + logPartStr + ' }';
return { json: Object.assign({}, dObj, { refuseBody: { query: queryStr, variables: { notes: notesStr, message: 'Substitution refused for ' + dObj.outgoingName + ': ' + dObj.reason, origin: cfgObj.ORIGIN_IDENTIFIER } } }) };

// If the refusal cannot be recorded, stop: otherwise the request would be retried
// on every run without anyone knowing why.
const decObj = $('Prepare Refusal').item.json;
const resObj = $json || {};
const dObj = resObj.data || {};
const tagObj = (dObj.tag || {}).update;
const logObj = decObj.eventId ? (dObj.log || {}).createExternalIntegrationLog : { errors: [] };
const errsAry = (resObj.errors || []).concat((tagObj && tagObj.errors) || []).concat((logObj && logObj.errors) || []);
if (!tagObj || !logObj || errsAry.length > 0) {
  throw new Error('Could not record the refused substitution for ' + decObj.outgoingName + ' (learner ' + decObj.learnerId + '): ' + (errsAry.map(function (eObj) { return eObj.message; }).join('; ') || 'missing response') + '. Reason it was refused: ' + decObj.reason);
}
return { json: { learnerId: decObj.learnerId, outcome: 'refused' } };
